    M("M121", "tick: now_ms not stored", ("    c->now_ms = now_ms;\n    c->ticked = true;", "    c->ticked = true;")),
    M("M122", "tick: ticked not stored", ("    c->now_ms = now_ms;\n    c->ticked = true;", "    c->now_ms = now_ms;")),
    M("M123", "tick: read_led failure ignored", ("if (c->hal.read_led_mask(c->hal.ctx, &mask) < 0) {", "if (c->hal.read_led_mask(c->hal.ctx, &mask) < -100) {")),
    M("M124", "tick: read_led failure -> no emergency release_all", ("        fault_and_release(c, KVM_CTRL_FAULT_READ_LED);", "        set_fault(c, KVM_CTRL_FAULT_READ_LED);")),
    M("M125", "tick: video_sync not sanitised", ("if (sync != KVM_VIDEO_SYNC_NO_SIGNAL && sync != KVM_VIDEO_SYNC_LOCKED) sync = KVM_VIDEO_SYNC_UNKNOWN;", "")),
    M("M126", "tick: last_sync not stored", ("    c->last_sync = sync;\n", "")),
    M("M127", "tick: video_sync not passed to kvm_logic", ("in.video_sync = sync;", "in.video_sync = KVM_VIDEO_SYNC_UNKNOWN;")),
    M("M128", "tick: led mask not converted (raw = mask)", ("in.led_raw_state = kvm_ctrl_led_mask_to_raw(mask);", "in.led_raw_state = mask;")),
    M("M129", "tick: apply failure ignored (returns OK)", ("    if (!apply_outputs(c, &out)) return KVM_CTRL_ERR_FAULT;\n    update_op(c, &out);", "    (void)apply_outputs(c, &out);\n    update_op(c, &out);")),
    M("M130", "tick: update_op before apply", ("    if (!apply_outputs(c, &out)) return KVM_CTRL_ERR_FAULT;\n    update_op(c, &out);", "    update_op(c, &out);\n    if (!apply_outputs(c, &out)) return KVM_CTRL_ERR_FAULT;")),
    M("M131", "tick: update_op skipped", ("    if (!apply_outputs(c, &out)) return KVM_CTRL_ERR_FAULT;\n    update_op(c, &out);", "    if (!apply_outputs(c, &out)) return KVM_CTRL_ERR_FAULT;\n    if (0) update_op(c, &out);")),
    M("M132", "tick: logic stepped with now_ms+1", ("kvm_logic_step(&c->logic, &in, now_ms, &out);", "kvm_logic_step(&c->logic, &in, now_ms + 1, &out);")),
    # ---- select ----
    M("M133", "select: channel 0 accepted", ("    if (channel < 1 || channel > 4) return KVM_CTRL_ERR_INVALID_PARAM;\n    if (c->fault) return KVM_CTRL_ERR_FAULT;\n    /* kvm_logic は", "    if (channel > 4) return KVM_CTRL_ERR_INVALID_PARAM;\n    if (c->fault) return KVM_CTRL_ERR_FAULT;\n    /* kvm_logic は")),
    M("M134", "select: channel 5 accepted", ("    if (channel < 1 || channel > 4) return KVM_CTRL_ERR_INVALID_PARAM;\n    if (c->fault) return KVM_CTRL_ERR_FAULT;\n    /* kvm_logic は", "    if (channel < 1 || channel > 5) return KVM_CTRL_ERR_INVALID_PARAM;\n    if (c->fault) return KVM_CTRL_ERR_FAULT;\n    /* kvm_logic は")),
    M("M135", "select: fault check removed", ("    if (c->fault) return KVM_CTRL_ERR_FAULT;\n    /* kvm_logic は", "    /* kvm_logic は")),
    M("M136", "select: unknown pre-check removed", ("    if (c->logic.state == KVM_STATE_UNKNOWN) return KVM_CTRL_ERR_UNKNOWN_STATE;\n    if (c->logic.state == KVM_STATE_IDLE && c->logic.current_outputs.active_channel == channel) {", "    if (c->logic.state == KVM_STATE_IDLE && c->logic.current_outputs.active_channel == channel) {")),
    M("M137", "select: already_selected compare inverted", ("c->logic.current_outputs.active_channel == channel) {\n        return KVM_CTRL_ALREADY_SELECTED;", "c->logic.current_outputs.active_channel != channel) {\n        return KVM_CTRL_ALREADY_SELECTED;")),
    M("M138", "select: already_selected ignores idle", ("if (c->logic.state == KVM_STATE_IDLE && c->logic.current_outputs.active_channel == channel) {", "if (c->logic.current_outputs.active_channel == channel) {")),
    M("M139", "select: already_selected removed", ("    if (c->logic.state == KVM_STATE_IDLE && c->logic.current_outputs.active_channel == channel) {\n        return KVM_CTRL_ALREADY_SELECTED;\n    }\n", "")),
    M("M140", "select: kvm_logic failure ignored", ("    if (r != KVM_RESULT_OK) return map_logic_result(r);\n\n    record_op(c, KVM_CTRL_OP_SELECT", "    if (r == 12345) return map_logic_result(r);\n\n    record_op(c, KVM_CTRL_OP_SELECT")),
    M("M141", "select: op recorded with POWER_PRESS kind", ("record_op(c, KVM_CTRL_OP_SELECT, channel, op_id);", "record_op(c, KVM_CTRL_OP_POWER_PRESS, channel, op_id);")),
    M("M142", "select: op_id not cleared on entry", ("kvm_ctrl_result_t kvm_ctrl_select(kvm_ctrl_t *c, uint8_t channel, uint32_t *op_id) {\n    if (op_id) *op_id = 0;", "kvm_ctrl_result_t kvm_ctrl_select(kvm_ctrl_t *c, uint8_t channel, uint32_t *op_id) {")),
    M("M143", "select: NOT_READY check removed", ("kvm_ctrl_result_t kvm_ctrl_select(kvm_ctrl_t *c, uint8_t channel, uint32_t *op_id) {\n    if (op_id) *op_id = 0;\n    if (!c) return KVM_CTRL_ERR_INVALID_PARAM;\n    if (!c->initialized) return KVM_CTRL_ERR_NOT_READY;",
                                                   "kvm_ctrl_result_t kvm_ctrl_select(kvm_ctrl_t *c, uint8_t channel, uint32_t *op_id) {\n    if (op_id) *op_id = 0;\n    if (!c) return KVM_CTRL_ERR_INVALID_PARAM;")),
    # ---- power ----
    M("M144", "power: PRESS maps to RESET target", ("target = KVM_ATX_TARGET_POWER;       kind", "target = KVM_ATX_TARGET_RESET;       kind")),
    M("M145", "power: RESET maps to POWER target", ("target = KVM_ATX_TARGET_RESET;       kind", "target = KVM_ATX_TARGET_POWER;       kind")),
    M("M146", "power: FORCE maps to POWER target", ("target = KVM_ATX_TARGET_POWER_FORCE; kind", "target = KVM_ATX_TARGET_POWER;       kind")),
    M("M147", "power: PRESS records RESET kind", ("kind = KVM_CTRL_OP_POWER_PRESS; pulse_ms", "kind = KVM_CTRL_OP_POWER_RESET; pulse_ms")),
    M("M148", "power: FORCE records PRESS kind", ("kind = KVM_CTRL_OP_POWER_FORCE; pulse_ms", "kind = KVM_CTRL_OP_POWER_PRESS; pulse_ms")),
    M("M149", "power: PRESS uses reset_ms", ("pulse_ms = c->config.press_ms; break;", "pulse_ms = c->config.reset_ms; break;")),
    M("M150", "power: RESET uses press_ms", ("pulse_ms = c->config.reset_ms; break;", "pulse_ms = c->config.press_ms; break;")),
    M("M151", "power: FORCE uses press_ms", ("pulse_ms = c->config.force_ms; break;", "pulse_ms = c->config.press_ms; break;")),
