    M("M153", "power: channel 0 accepted (range check removed lower bound)", ("kvm_ctrl_result_t kvm_ctrl_power(kvm_ctrl_t *c, uint8_t channel, kvm_ctrl_power_action_t action, uint32_t *op_id) {\n    if (op_id) *op_id = 0;\n    if (!c) return KVM_CTRL_ERR_INVALID_PARAM;\n    if (!c->initialized) return KVM_CTRL_ERR_NOT_READY;\n    if (channel < 1 || channel > 4) return KVM_CTRL_ERR_INVALID_PARAM;",
                                                                      "kvm_ctrl_result_t kvm_ctrl_power(kvm_ctrl_t *c, uint8_t channel, kvm_ctrl_power_action_t action, uint32_t *op_id) {\n    if (op_id) *op_id = 0;\n    if (!c) return KVM_CTRL_ERR_INVALID_PARAM;\n    if (!c->initialized) return KVM_CTRL_ERR_NOT_READY;\n    if (channel > 4) return KVM_CTRL_ERR_INVALID_PARAM;")),
    M("M154", "power: channel 5 accepted", ("    if (!c->initialized) return KVM_CTRL_ERR_NOT_READY;\n    if (channel < 1 || channel > 4) return KVM_CTRL_ERR_INVALID_PARAM;\n\n    kvm_atx_target_t target;", "    if (!c->initialized) return KVM_CTRL_ERR_NOT_READY;\n    if (channel < 1 || channel > 5) return KVM_CTRL_ERR_INVALID_PARAM;\n\n    kvm_atx_target_t target;")),
    M("M155", "power: kvm_logic failure ignored", ("    if (r != KVM_RESULT_OK) return map_logic_result(r);\n    if (cooldown_remaining(c) > 0)", "    if (r == 12345) return map_logic_result(r);\n    if (cooldown_remaining(c) > 0)")),
    M("M156", "power: cooldown always rejects", ("if (cooldown_remaining(c) > 0) return KVM_CTRL_ERR_COOLDOWN;", "if (cooldown_remaining(c) > 0 || 1) return KVM_CTRL_ERR_COOLDOWN;")),
    M("M157", "power: cooldown check removed", ("    if (cooldown_remaining(c) > 0) return KVM_CTRL_ERR_COOLDOWN;\n", "")),
    M("M158", "power: cooldown checked before kvm_logic (order)", ("    kvm_logic_t trial = c->logic;\n    kvm_result_t r = kvm_logic_request_atx(&trial, channel, target, pulse_ms);\n    if (r != KVM_RESULT_OK) return map_logic_result(r);\n    if (cooldown_remaining(c) > 0) return KVM_CTRL_ERR_COOLDOWN;\n",
                                                      "    kvm_logic_t trial = c->logic;\n    if (cooldown_remaining(c) > 0) return KVM_CTRL_ERR_COOLDOWN;\n    kvm_result_t r = kvm_logic_request_atx(&trial, channel, target, pulse_ms);\n    if (r != KVM_RESULT_OK) return map_logic_result(r);\n")),
    M("M159", "power: accepted trial not committed", ("    c->logic = trial;\n    c->atx_has_last = true;", "    c->atx_has_last = true;")),
    M("M160", "power: request applied to real logic before cooldown check", ("    kvm_logic_t trial = c->logic;\n    kvm_result_t r = kvm_logic_request_atx(&trial, channel, target, pulse_ms);", "    kvm_logic_t *trialp = &c->logic;\n    kvm_logic_t trial = *trialp;\n    kvm_result_t r = kvm_logic_request_atx(trialp, channel, target, pulse_ms);"),
                                                                          ("    c->logic = trial;\n    c->atx_has_last = true;", "    (void)trial;\n    c->atx_has_last = true;")),
    M("M161", "power: atx_has_last not set", ("    c->atx_has_last = true;\n    c->atx_last_ms", "    c->atx_last_ms")),
    M("M162", "power: atx_last_ms not recorded", ("    c->atx_last_ms = c->now_ms;\n", "")),
    M("M163", "power: cooldown started at time 0 instead of now", ("    c->atx_last_ms = c->now_ms;\n", "    c->atx_last_ms = 0;\n")),
    M("M164", "power: cooldown also set for non-accepted (set before trial result)", ("    kvm_logic_t trial = c->logic;\n", "    c->atx_has_last = true; c->atx_last_ms = c->now_ms;\n    kvm_logic_t trial = c->logic;\n")),
    M("M165", "power: op recorded with SELECT kind", ("    record_op(c, kind, channel, op_id);\n    return KVM_CTRL_OK;\n}\n\nstatic kvm_ctrl_state_t", "    (void)kind;\n    record_op(c, KVM_CTRL_OP_SELECT, channel, op_id);\n    return KVM_CTRL_OK;\n}\n\nstatic kvm_ctrl_state_t")),
    M("M166", "power: op_id not cleared on entry", ("kvm_ctrl_result_t kvm_ctrl_power(kvm_ctrl_t *c, uint8_t channel, kvm_ctrl_power_action_t action, uint32_t *op_id) {\n    if (op_id) *op_id = 0;", "kvm_ctrl_result_t kvm_ctrl_power(kvm_ctrl_t *c, uint8_t channel, kvm_ctrl_power_action_t action, uint32_t *op_id) {")),
    # ---- status ----
    M("M167", "map_state: TRACKING -> SWITCHING", ("        case KVM_STATE_MANUAL_TRACK_WAIT_LED:\n        case KVM_STATE_MANUAL_TRACK_WAIT_VIDEO:\n            return KVM_CTRL_STATE_TRACKING;", "        case KVM_STATE_MANUAL_TRACK_WAIT_LED:\n        case KVM_STATE_MANUAL_TRACK_WAIT_VIDEO:\n            return KVM_CTRL_STATE_SWITCHING;")),
    M("M168", "map_state: ATX -> IDLE", ("        case KVM_STATE_ATX_WAIT_SETUP:\n        case KVM_STATE_ATX_PULSE:\n            return KVM_CTRL_STATE_ATX;", "        case KVM_STATE_ATX_WAIT_SETUP:\n        case KVM_STATE_ATX_PULSE:\n            return KVM_CTRL_STATE_IDLE;")),
    M("M169", "map_state: SWITCH_REVERT_SETUP -> TRACKING", ("        case KVM_STATE_SWITCH_REVERT_SETUP:\n            return KVM_CTRL_STATE_SWITCHING;", "        case KVM_STATE_SWITCH_REVERT_SETUP:\n            return KVM_CTRL_STATE_TRACKING;")),
    M("M170", "map_state: UNKNOWN -> IDLE", ("        case KVM_STATE_UNKNOWN:\n        default:\n            return KVM_CTRL_STATE_UNKNOWN;", "        case KVM_STATE_UNKNOWN:\n        default:\n            return KVM_CTRL_STATE_IDLE;")),
    M("M171", "status: active_channel not zeroed when unknown", ("status->active_channel = (status->state == KVM_CTRL_STATE_UNKNOWN) ? 0 : c->logic.current_outputs.active_channel;", "status->active_channel = c->logic.current_outputs.active_channel;")),
    M("M172", "status: active_channel zeroed when idle too", ("status->active_channel = (status->state == KVM_CTRL_STATE_UNKNOWN) ? 0 : c->logic.current_outputs.active_channel;", "status->active_channel = (status->state != KVM_CTRL_STATE_TRACKING) ? 0 : c->logic.current_outputs.active_channel;")),
    M("M173", "status: atx_locked inverted", ("status->atx_locked = c->logic.current_outputs.atx_locked;", "status->atx_locked = !c->logic.current_outputs.atx_locked;")),
    M("M174", "status: atx_anomaly always false", ("status->atx_anomaly = c->logic.current_outputs.atx_anomaly_detected;", "status->atx_anomaly = false;")),
